// Service worker: caches the app so it works offline once installed.
// Network-first, so new recipes show up as soon as you're online. Bump VERSION when adding files.
const VERSION = 'cookbook-v3';
const FILES = [
  './',
  'index.html',
  'styles.css',
  'app.js',
  // recipes:start (generated by tools/format-recipes.js)
  'recipes/africa.js',
  'recipes/asia.js',
  'recipes/caribbean.js',
  'recipes/europe.js',
  'recipes/middle-east.js',
  'recipes/north-america.js',
  'recipes/south-america.js',
  // recipes:end
  'manifest.webmanifest',
  'icons/icon.svg',
  'icons/icon-180.png',
  'icons/icon-192.png',
  'icons/icon-512.png',
  'icons/icon-maskable-512.png'
];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(VERSION).then(c => c.addAll(FILES)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k !== VERSION).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', e => {
  if (e.request.method !== 'GET' || new URL(e.request.url).origin !== location.origin) return;
  e.respondWith(
    fetch(e.request)
      .then(res => {
        const copy = res.clone();
        caches.open(VERSION).then(c => c.put(e.request, copy));
        return res;
      })
      .catch(() => caches.match(e.request, { ignoreSearch: true }).then(r => r || caches.match('index.html')))
  );
});

self.addEventListener('notificationclick', e => {
  e.notification.close();
  e.waitUntil(self.clients.matchAll({ type: 'window' }).then(cs => (cs[0] ? cs[0].focus() : self.clients.openWindow('./'))));
});
